COMMENT ON COLUMN L_APPLICATION.APPLICATION_ID IS 'APPLICATION ID: Unique identifier for applications you make for continuations, licenses etc. to the government.';
COMMENT ON COLUMN L_APPLICATION.APPLICATION_TYPE IS 'APPLICATION TYPE: continuation, groupings, license validations, offset notice appeal, selections, grouping, continuation, significant discovery area, significant discovery license, expiry notification, commercial discovery area, production license
-- . The type of application being made, such as application to drill, application to extend a land right, application to conduct geophysical operations etc.';
COMMENT ON COLUMN L_APPLICATION.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
