COMMENT ON COLUMN L_SP_POLYGON.CONTAINED_BY_POLYGON_ID IS 'CONTAINED BY POLYGON IDENTIFIER:  the unique identifier of a polygon that contains this one. Usually used in the case where the inner polygon represents an area of exclusion to the outer polygon. The outer polygon may contain one or more suc
-- h exclusions.';
COMMENT ON COLUMN L_SP_POLYGON.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_SP_POLYGON.EXCLUSION_IND IS 'EXCLUSION IND:   Indicates whether the polygon is an area of exclusion (Y= the area is an exclusion)';
COMMENT ON COLUMN L_SP_POLYGON.POLYGON_ID IS 'POLYGON ID:  Unique identifier to track multiple polygons';
COMMENT ON COLUMN L_SP_POLYGON.POLYGON_SET_ID IS 'POLYGON SET IDENTIFIER:  Use this column when a spatial description requires multiple polygons and more than one set of the polygons may be stored for use (such as at different scales). Each set is grouped by the SET ID.';
COMMENT ON COLUMN L_SP_POLYGON.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_SP_POLYGON.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_SP_POLYGON.SPATIAL_DESCRIPTION_ID IS 'SPATIAL DESCRIPTION:  The surface and sub-surface description of any object that occupies an area, such as a land right, field, facility or area of interest.';
COMMENT ON COLUMN L_SP_POLYGON.SPATIAL_OBS_NO IS 'SPATIAL DESCRIPTION OBSERVATION NUMERIC:  a unique series NUMERIC for the spatial description, allowing the spatial description to be versioned over time.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.BASE_MD IS 'BASE MEASURED DEPTH:  Measured depth from the surface to the base of the zone interval.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.BASE_STRAT_UNIT_ID IS 'BASE STRATIGRAPHIC UNIT IDENTIFIER:  unique identifier for the stratigraphic unit that is at the base of the land zone.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.EXCLUDED_IND IS 'SUBSTANCE EXCLUDED INDICATOR:  a yes / no flag indicating that this substance is not included in the land mineral rights. This information is generally not provided by the agreement, but may be added to facilitate queries as needed.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.INCLUDED_IND IS 'SUBSTANCE INCLUDED INDICATOR:  a yes / no flag indicating that this substance is explicitly included in the land mineral rights.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.MINERAL_ZONE_ID IS 'MINERAL ZONE ID:  unique identifier for the mineral zone';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.SPATIAL_DESCRIPTION_ID IS 'SPATIAL DESCRIPTION:  The surface and sub-surface description of any object that occupies an area, such as a land right, field, facility or area of interest.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.SPATIAL_OBS_NO IS 'SPATIAL DESCRIPTION OBSERVATION NUMERIC:  a unique series NUMERIC for the spatial description, allowing the spatial description to be versioned over time.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.STRAT_NAME_SET_ID IS 'STRAT NAME SET IDENTIFIER:  Unique identifier for the stratigraphic name set. A stratigraphic name set is an unordered collection of stratigraphic units, that may be in use for a Lexicon, a geographic area, a project, a company etc.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.SUBSTANCE IS 'SUBSTANCE:  scientifically refers to chemical element or compound occurring naturally as a product of inorganic processes found beneath the earths surface and possessing some commercial value.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.TOP_MD IS 'TOP MEASURED DEPTH:  Measured depth from the surface to the top of the zone interval.';
COMMENT ON COLUMN L_SP_ZONE_SUBSTANCE.TOP_STRAT_UNIT_ID IS 'TOP STRATIGRAPHIC UNIT IDENTIFIER:  unique identifier for the stratigraphic unit that is at the top of the land zone.';
COMMENT ON COLUMN L_STRAT_NAME_SET.BUSINESS_ASSOCIATE IS 'BUSINESS ASSOCIATE:  Unique identifier for a business associate, such as a person, company, regulatory agency, government or consortium.';
COMMENT ON COLUMN L_STRAT_NAME_SET.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_STRAT_NAME_SET.EFFECTIVE_DATE IS 'EFFECTIVE DATE:  Date on which the item became a viable entity.';
COMMENT ON COLUMN L_STRAT_NAME_SET.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_STRAT_NAME_SET.PREFERRED_IND IS 'PREFERRED INDICATOR:  A yes / no flag indicating that this row is the preferred version, and should be used by default.';
COMMENT ON COLUMN L_STRAT_NAME_SET.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_STRAT_NAME_SET.STRAT_NAME_SET_ID IS 'STRAT NAME SET IDENTIFIER:  Unique identifier for the stratigraphic name set. A stratigraphic name set is an unordered collection of stratigraphic units, that may be in use for a Lexicon, a geographic area, a project, a company etc.';
COMMENT ON COLUMN L_STRAT_UNIT.AVERAGE_AGE IS 'AVERAGE AGE CODE:  A NUMERIC that indicates the age of a stratigraphic unit relative to others in the same strat name set. Higher numbers are older than lower numbers. ';
COMMENT ON COLUMN L_STRAT_UNIT.BUSINESS_ASSOCIATE IS 'BUSINESS ASSOCIATE:  Unique identifier for a business associate, such as a person, company, regulatory agency, government or consortium.';
COMMENT ON COLUMN L_STRAT_UNIT.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_STRAT_UNIT.EFFECTIVE_DATE IS 'EFFECTIVE DATE:  Date on which the item became a viable entity.';
COMMENT ON COLUMN L_STRAT_UNIT.FAULT_TYPE IS 'FAULT TYPE:  Usage of this column will be evaluated by future work groups to determine how it should be used (or deprecated) in the model.';
COMMENT ON COLUMN L_STRAT_UNIT.FORM_CODE IS 'FORMATION CODE:  code given to the formation name.';
COMMENT ON COLUMN L_STRAT_UNIT.LONG_NAME IS 'LONG NAME:  Common long name given to reference type or code.';
COMMENT ON COLUMN L_STRAT_UNIT.MAX_AGE IS 'MAX AGE CODE:  A NUMERIC that indicates the age of a stratigraphic unit relative to others in the same strat name set. Higher numbers are older than lower numbers. ';
COMMENT ON COLUMN L_STRAT_UNIT.MIN_AGE IS 'MIN AGE CODE:  A NUMERIC that indicates the age of a stratigraphic unit relative to others in the same strat name set.  Higher numbers are older than lower numbers.';
COMMENT ON COLUMN L_STRAT_UNIT.ORDINAL_AGE_CODE IS 'ORDINAL AGE CODE:  A NUMERIC that indicates the age of a stratigraphic unit relative to others in the same strat name set. Higher numbers are older than lower numbers. This column may be used to assist in locating all stratigraphic units older or yo
-- unger than a specified unit.';
COMMENT ON COLUMN L_STRAT_UNIT.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_STRAT_UNIT.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_STRAT_UNIT.STRAT_NAME_SET_ID IS 'STRAT NAME SET IDENTIFIER:  Unique identifier for the stratigraphic name set. A stratigraphic name set is an unordered collection of stratigraphic units, that may be in use for a Lexicon, a geographic area, a project, a company etc.';
COMMENT ON COLUMN L_STRAT_UNIT.STRAT_UNIT_ID IS 'STRATIGRAPHIC UNIT IDENTIFIER:  unique identifier for the stratigraphic unit.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.INTERPRETER IS 'INTERPRETER:  The business associate who interpreted this well section.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.INTERP_ID IS 'INTERPRETATION IDENTIFIER:  a unique NUMERIC added to enable a single strat unit to be identified more than once as part of a stratigraphic column. Multiple occurances may occur for many reasons, including folding, faulting or a non-vertical interp
-- retation of the strat column.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.ORDINAL_SEQ_NO IS 'ORDINAL SEQUENCE NUMERIC:  sequence in which this unit occurs in the column, from surface to base';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.OVERTURNED_IND IS 'OVERTURNED INDICATOR:  a yes / no flag indicating that the strat unit is part of an overturned section and that the normal sequnce of occurrence is reversed.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.PICK_DATE IS 'PICK DATE:  the date that the pick was made.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.PICK_TVD IS 'PICK TRUE VERTICAL DEPTH:  True vertical depth from the surface datum to the pick of the formation top.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.STRAT_NAME_SET_ID IS 'STRAT NAME SET IDENTIFIER:  Unique identifier for the stratigraphic name set. A stratigraphic name set is an unordered collection of stratigraphic units, that may be in use for a Lexicon, a geographic area, a project, a company etc.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.STRAT_UNIT_AGE IS 'STRAT UNIT AGE:  The age in years of the stratigraphic unit.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.STRAT_UNIT_ID IS 'STRATIGRAPHIC UNIT IDENTIFIER:  unique identifier for the stratigraphic unit.';
COMMENT ON COLUMN L_STRAT_WELL_SECTION.UWI IS 'UNIQUE WELL IDENTIFIER:  A unique name, code or NUMERIC designated as the primary key for this row.';
COMMENT ON COLUMN L_WELL.ALT_WELL_NAME IS 'ALT_WELL_NAME: Name or code assigned to a well by a partner, agency or application.';
COMMENT ON COLUMN L_WELL.AOF_COUNT IS 'AOF_COUNT:  The NUMERIC of Absolute Open Flow''s that were done on this well.';
COMMENT ON COLUMN L_WELL.ASSIGNED_FIELD IS 'ASSIGNED FIELD:  The field that this well is assigned to for production purposes.';
COMMENT ON COLUMN L_WELL.BASIN IS 'BASIN: Common name give to reference type.';
COMMENT ON COLUMN L_WELL.BOTTOM_HOLE_LATITUDE IS 'BH_LATITUDE: Latitude of bottom hole point projected to surface.';
COMMENT ON COLUMN L_WELL.BOTTOM_HOLE_LOC_QUALITY IS 'BH_QUALITY: Description of the accuracy of the BH_LONGITUDE and BH_LATITUDE';
COMMENT ON COLUMN L_WELL.BOTTOM_HOLE_LONGITUDE IS 'BH_LONGITUDE: Longitude of bottom hole point projected to surface.';
COMMENT ON COLUMN L_WELL.COMPLETION_DATE IS 'COMPLETION_DATE: The date on the official filing or completion report indicating the well is established as ready to produce, inject or abandon.';
COMMENT ON COLUMN L_WELL.COMP_COUNT IS 'COMP_COUNT:  The NUMERIC of completions that were done on the well.';
COMMENT ON COLUMN L_WELL.CONFIDENTIAL_DATE IS 'CONFIDENTIAL DATE:  Date confidential information can be released to the general public.';
COMMENT ON COLUMN L_WELL.CORE_COUNT IS 'CORE_COUNT:  The NUMERIC of cores cut in this well.';
COMMENT ON COLUMN L_WELL.COUNTRY IS 'REFERENCE COUNTRY:  A reference table identifying a division of land, political nation or territory. For example Austria, Canada, United Kingdom, USA, Venezula.';
COMMENT ON COLUMN L_WELL.CURRENT_CLASS IS 'WELL CLASS:  REFERENCE WELL CLASSIFICATION:  A reference table identifying the classification of a well commonly based on the Lahee system. For example New Field Wildcat, Deeper Pool Test, Outpost or Development';
COMMENT ON COLUMN L_WELL.CURRENT_STATUS IS 'CURRENT_STATUS: Description of the actual status of the well on a specific date. ';
COMMENT ON COLUMN L_WELL.CURRENT_STATUS_DATE IS 'CURRENT STATUS DATE:  Date of the current status of the well.';
COMMENT ON COLUMN L_WELL.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_WELL.DATUM IS 'DATUM: The name of the datum associated to the SH_LATITUDE and SH_LONGITUDE attributes';
COMMENT ON COLUMN L_WELL.DIR_SRVY_COUNT IS 'DIR_SRVY_COUNT:  The NUMERIC of directional survey''s that were run on this well.';
COMMENT ON COLUMN L_WELL.DRILL_RIG_NUM IS 'DRILL RIG NUMERIC:  The NUMERIC of the drill rig used to drill the well.';
COMMENT ON COLUMN L_WELL.DRILL_TD IS 'DRILL_TD: Total or maximum depth of the well as reported by the operator / driller.';
COMMENT ON COLUMN L_WELL.DST_COUNT IS 'DST_COUNT:  The NUMERIC of Drill Stem Tests that were run in this well.';
COMMENT ON COLUMN L_WELL.FINAL_DRILL_DATE IS 'FINAL DRILL DATE:  Date the drilling operations for the well were finalized.';
COMMENT ON COLUMN L_WELL.FINAL_TD IS 'FINAL TOTAL DEPTH:  The actual measurement along the well path from the reference datum to the bottom of the well.';
COMMENT ON COLUMN L_WELL.GROUND_ELEV IS 'GROUND ELEVEVATION:  The elevation of the ground at the well site.';
COMMENT ON COLUMN L_WELL.IPTS_COUNT IS 'IPTS_COUNT:  The NUMERIC of presssure tests that were run in this well.';
COMMENT ON COLUMN L_WELL.KB_ELEV IS 'KELLY BUSHING ELEVATION:  The elevation of the kelly bushing (generally measured from sea level)';
COMMENT ON COLUMN L_WELL.LAST_INJECTION_DATE IS 'LAST INJECTION DATE: The date that injection volumes were last reported for this entity.';
COMMENT ON COLUMN L_WELL.LAST_PRODUCTION_DATE IS 'LAST PRODUCTION DATE:  The date that production was last reported for this entity.';
COMMENT ON COLUMN L_WELL.LEASE IS 'LEASE: Name assigned to the lease by the regulatory agency with jurisdiction over the minerals in the area where the lease is located.';
COMMENT ON COLUMN L_WELL.LICENSEE IS 'LICENSEE:  The Business Associate representing the licensee of the well.';
COMMENT ON COLUMN L_WELL.LICENSE_DATE IS 'LICENSE_DATE: Date the well was issued.';
COMMENT ON COLUMN L_WELL.LICENSE_NUMBER IS 'LICENSE_NUMBER: License NUMERIC for the permit to drill.';
COMMENT ON COLUMN L_WELL.LOG_COUNT IS 'LOG_COUNT:  The NUMERIC of logs that were run on this well.';
COMMENT ON COLUMN L_WELL.MAX_TVD IS 'MAXIMUM TRUE VERTICAL DEPTH:  The maximum true vertical depth from the surface datum reference to the final total depth or deepest point, measured on a straight line.';
COMMENT ON COLUMN L_WELL.OLDEST_STRAT_AGE IS 'OLDEST STRAT AGE:  The age in years of the stratigraphic unit.';
COMMENT ON COLUMN L_WELL.OLDEST_STRAT_UNIT_ID IS 'STRATIGRAPHIC UNIT IDENTIFIER:  unique identifier for the stratigraphic unit.';
COMMENT ON COLUMN L_WELL.ON_INJECTION_DATE IS 'ON INJECTION DATE: The date that injection was first reported for this entity.';
COMMENT ON COLUMN L_WELL.ON_PRODUCTION_DATE IS 'ON PRODUCTION DATE:  The date that production was first reported for this entity.';
COMMENT ON COLUMN L_WELL.OPERATOR IS 'OPERATOR:  The Business Associate representing the owners of the well, responsible for the operations of drilling and producing the well and for reporting these activities to the partners and regulatory agencies.';
COMMENT ON COLUMN L_WELL.OPERATOR_ABBREVIATION IS 'OPERATOR_ABBREVIATION: Common short name used for OPERATOR.';
COMMENT ON COLUMN L_WELL.PARENT_RELATIONSHIP_TYPE IS 'PARENT RELATIONSHIP TYPE: Indicates the type of relationship between well and well bore, such as side track, reentry etc.';
COMMENT ON COLUMN L_WELL.PARENT_UWI IS 'UNIQUE WELL IDENTIFIER:  A unique name, code or NUMERIC designated as the primary key for this row.';
COMMENT ON COLUMN L_WELL.PLOT_SYMBOL IS 'PLOT_SYMBOL:  The identifier for the type of symbol to plot on a map.';
COMMENT ON COLUMN L_WELL.POOL IS 'POOL: The name of the pool.';
COMMENT ON COLUMN L_WELL.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_WELL.PRODUCING_HORIZON IS 'PRODUCING_HORIZON: The name of the formation from which the well is producing.';
COMMENT ON COLUMN L_WELL.PRODUCING_STATUS IS 'PRODUCING_STATUS: The result of the well (i.e. currently producing, abandoned, shut-in, completed).';
COMMENT ON COLUMN L_WELL.PRODUCING_STRAT_AGE IS 'PRODUCING_STRAT_AGE: The age of the formation from which the well is producing.';
COMMENT ON COLUMN L_WELL.PROFILE_TYPE IS 'WELLBORE SHAPE:  A reference table describing a type of wellbore shape. For example vertical, horizontal, directional or s-shaped.';
COMMENT ON COLUMN L_WELL.PROSPECT_NAME IS 'PROSPECT NAME:  The name of the prospect that this well as drilled as/into.';
COMMENT ON COLUMN L_WELL.PROVINCE_STATE IS 'PROVINCE STATE:  A reference table identifying valid states, provinces or other political subdivisions of countries. For example, Colorado, Texas in the US, Alberta in Canada';
COMMENT ON COLUMN L_WELL.REGION IS 'REGION: Name of the geographic region the well is situated in.';
COMMENT ON COLUMN L_WELL.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_WELL.RIG_RELEASE_DATE IS 'RIG RELEASE DATE:  Date the drilling rig can be released from operations and moved from the well site as specified in the contract.';
COMMENT ON COLUMN L_WELL.ROW_CHANGED_DATE IS 'ROW CHANGED DATE:  System date of the last time the row was changed.';
COMMENT ON COLUMN L_WELL.SITUATION IS 'SITUATION: Description of the accuracy of the SH_LONGITUDE and SH_LATITUDE.';
COMMENT ON COLUMN L_WELL.SPUD_DATE IS 'SPUD DATE:  Date the drilling operations commenced on the well. The first day hole is made.';
COMMENT ON COLUMN L_WELL.STATUS_TYPE IS 'STATUS TYPE:  The type of status reported for the well. Can include construction status, operating status, producing status, abandonment status etc.';
COMMENT ON COLUMN L_WELL.SURFACE_LATITUDE IS 'SH_LATITUDE: Angular distance in decimal degrees, north or south of the equator. A positive value represents a north latitude.';
COMMENT ON COLUMN L_WELL.SURFACE_LOC_QUALITY IS 'SH_QUALITY: Description of the accuracy of the SH_LONGITUDE and SH_LATITUDE.';
COMMENT ON COLUMN L_WELL.SURFACE_LONGITUDE IS 'SH_LONGITUDE: Angular distance in decimal degrees, east or west of the equator. A negative value represents a west longitude.';
COMMENT ON COLUMN L_WELL.SURFACE_UWI IS 'SURFACE_UWI:  The surface location or UWI for the well.';
COMMENT ON COLUMN L_WELL.SURVEY_GRID IS 'SURVEY_GRID: A collection of polygon features used to represent a survey grid. ';
COMMENT ON COLUMN L_WELL.SU_COUNT IS 'SU_COUNT:  The NUMERIC of stratigraphic units picked in this well.';
COMMENT ON COLUMN L_WELL.TD_FORMATION IS 'TD_FORMATION: The name of the formation at the bottom hole location.';
COMMENT ON COLUMN L_WELL.TD_STRAT_AGE IS 'TD_STRAT_AGE: The age of the formation at the bottom hole location.';
COMMENT ON COLUMN L_WELL.TD_STRAT_NAME_SET_ID IS 'STRAT NAME SET IDENTIFIER:  Unique identifier for the stratigraphic name set. A stratigraphic name set is an unordered collection of stratigraphic units, that may be in use for a Lexicon, a geographic area, a project, a company etc.';
COMMENT ON COLUMN L_WELL.TD_STRAT_UNIT_ID IS 'STRATIGRAPHIC UNIT IDENTIFIER: unique identifier for the stratigraphic unit.';
COMMENT ON COLUMN L_WELL.UWI IS 'UNIQUE WELL IDENTIFIER:  A unique name, code or NUMERIC designated as the primary key for this row.';
COMMENT ON COLUMN L_WELL.VEL_SRVY_COUNT IS 'VEL SRVY COUNT:  The count of the velocity surveys done in this well.';
COMMENT ON COLUMN L_WELL.WATER_DEPTH IS 'WATER DEPTH:  Depth of the water at a well (measured from the water level to the mud line).';
COMMENT ON COLUMN L_WELL.WATER_DEPTH_DATUM IS 'WATER DATUM:  Reference datum to which the water depth is referenced, such as mean sea level.';
COMMENT ON COLUMN L_WELL.WELL_NAME IS 'WELL NAME:  Name assigned to the well. This may be the legal or registered name as it appears on a permit or a given name assigned by the operator.';
COMMENT ON COLUMN L_WELL.WELL_NUMBER IS 'WELL_NUMBER: NUMERIC or alphanumeric name assigned to each well by the operator. For example J21 or 10-26.';
COMMENT ON COLUMN L_WELL.WELL_NUMERIC_ID IS 'WELL NUMERIC IDENTIFIER:  A unique numeric identifier that is used to enhance performance of spatial queries using the intersection table WELL_GEOMETRY. Although this column is defined as OPTIONAL, if used at all, procedures should ensure that no duplicat
-- es are permitted (including NULLs).';
COMMENT ON COLUMN L_WELL.WELL_TYPE IS 'WELL_TYPE: A generic grouping for the type of well (i.e Oil, Gas, Water, Injection).';
COMMENT ON COLUMN L_WELL_ALIAS.ALIAS_TYPE IS 'ALIAS TYPE:  The type of alias, such as partner, historical, records etc.';
COMMENT ON COLUMN L_WELL_ALIAS.DATA_SOURCE IS 'DATA SOURCE: Identifies what transaction based system the row of data originated from.';
COMMENT ON COLUMN L_WELL_ALIAS.PPDM_GUID IS 'PPDM GUID:  This value may be used to provide a global unique identifier for this row of data. If used, optional PPDM NOT NULL constraints should be created.';
COMMENT ON COLUMN L_WELL_ALIAS.PREFERRED_IND IS 'PREFERRED INDICATOR:  A yes / no flag indicating that this row is the preferred version, and should be used by default.';
COMMENT ON COLUMN L_WELL_ALIAS.REMARK IS 'REMARK:  General remarks about this row of data';
COMMENT ON COLUMN L_WELL_ALIAS.SOURCE IS 'SOURCE:  The individual, company, agency, application or other source designated as the source of information for this row.';
COMMENT ON COLUMN L_WELL_ALIAS.UWI IS 'UNIQUE WELL IDENTIFIER:  A unique name, code or NUMERIC designated as the primary key for this row.';
COMMENT ON COLUMN L_WELL_ALIAS.WELL_ALIAS IS 'WELL ALIAS:  Full alias name or code assigned to a well by a partner, agency or application.';
COMMENT ON COLUMN L_WELL_ALIAS.WELL_ALIAS_ID IS 'WELL ALIAS:  Alternate or previous name/identifier assigned to the well.';
