COMMENT ON COLUMN L_WELL_SERVICE.BASE_STRAT_UNIT_AGE IS 'BASE STRAT UNIT AGE:  The age, in years of the stratigraphic unit.';
COMMENT ON COLUMN L_WELL_SERVICE.BASE_STRAT_UNIT_ID IS 'BASE STRATIGRAPHIC UNIT IDENTIFIER:  unique identifier for the stratigraphic unit that is at the base of the land zone.';
