COMMENT ON COLUMN L_WELL_SERVICE.SERVICE_DATE IS 'SERVICE DATE:  the date that the service provided was completed.';
COMMENT ON COLUMN L_WELL_SERVICE.SERVICE_NUMBER IS 'SERVICE_NUMBER:  The NUMERIC of the run within the SERVICE_TYPE.';
COMMENT ON COLUMN L_WELL_SERVICE.SERVICE_TABLE IS 'SERVICE_TABLE:  The name of the PPDM 3.7 table where the data for the row has come from.';
COMMENT ON COLUMN L_WELL_SERVICE.SERVICE_TYPE IS 'SERVICE_TYPE:  Most the the PPDM 3.7 tables store the type of work that was done, such as a core or cement job, a DST run, etc.';
