COMMENT ON TABLE L_APPLICATION IS 'L_APPLICATION:  Applications make for authority or permission, such as for extensions or continuations to the primary term of the agreement or for licenses.';
COMMENT ON TABLE L_AREA IS 'L_AREA:  Describes a geographical area of any type.';
COMMENT ON TABLE L_AREA_ALIAS IS 'L_AREA_ALIAS:  Areas may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_BA_ADDRESS IS 'L_BA_ADDRESS:  This table contains information on the address, phone numbers and location of the business associate, allowing for multiple addresses to be stored.';
COMMENT ON TABLE L_BA_ALIAS IS 'L_BA_ALIAS:  This table stores multiple alias names for a given business associate.  It allows the system to translate all of the multiple names into one common name.';
COMMENT ON TABLE L_BUSINESS_ASSOCIATE IS 'L_BUSINESS_ASSOCIATE:  This table is based on the BUSINESS_ASSOCIATE table.  It has substantially less columns though.';
COMMENT ON TABLE L_CONTRACT IS 'L_CONTRACT:  A binding agreement between two or more parties for the express purpose of sharing risk with associated revenue and expenses in a exploitation or exploration undertaking or the joint building of a oil and gas production facility.';
COMMENT ON TABLE L_CONTRACT_COMPONENT IS 'L_CONTRACT_COMPONENT:  A table that associates a contract with land rights, seismic lines, projects, wells, etc.';
COMMENT ON TABLE L_CONT_ALIAS IS 'L_CONT_ALIAS:  A contract reference NUMERIC related to another business associates internal contract reference.';
COMMENT ON TABLE L_CONT_EXTENSION IS 'L_CONT_EXTENSION:  This table is used to describe extensions beyond the primary term this is granted to a contract.';
COMMENT ON TABLE L_CS_COORDINATE_SYSTEM IS 'L_CS_COORDINATE_SYSTEM:  A rolled up table that contains the esstential information needed to display data on a map.  It contains data from CS_ELLIPSOID, CS_GEODETIC_DATUM and CS_PRINCIPLE_MERIDIAN.';
COMMENT ON TABLE L_ENTITLEMENT IS 'L_ENTITLEMENT:  This table describes access and use privleges or rights that are held by a person or organization.';
COMMENT ON TABLE L_ENT_COMPONENT IS 'L_ENT_COMPONENT:  The business objects defined in PPDM whose entitlement properties are managed by the entitlement description.  May include wells, components of wells, seismic data, land rights, etc.';
COMMENT ON TABLE L_ENT_GROUP IS 'L_ENT_GROUP:  This table is used to capture which security groups have access of varying types to the entitlement type.';
COMMENT ON TABLE L_FACILITY IS 'L_FACILITY:  A collection of surface equipment and meters which facilitate the production, injection or disposition of product.  This equipment supports any operation in the processing, development and transportation of product.';
COMMENT ON TABLE L_FACILITY_ALIAS IS 'L_FACILITY_ALIAS:  Facilities may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_FACILITY_SUBSTANCE IS 'L_FACILITY_SUBSTANCE:  This table is used to track the ability of a facility to handle substances.';
COMMENT ON TABLE L_FACILITY_XREF IS 'L_FACILITY_XREF:  This is used to track relationships between facilities.  Examples include tanks in a tank group, pipelines that feed into tanks, etc.';
COMMENT ON TABLE L_FIELD IS 'L_FIELD:  A geographical area defined for administrative and legal purposes.  The field name usually refers to the surface area, although at times it may refer to both the surface and the undergound productive zones.';
COMMENT ON TABLE L_FIELD_ALIAS IS 'L_FIELD_ALIAS:  Fields may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_FINANCE IS 'L_FINANCE:  Summary information about a financial reference, such as an AFE for an activity, such as seismic acquisition or processing.  Could be a cost centre or any other reference NUMERIC.';
COMMENT ON TABLE L_FIN_COMPONENT IS 'L_FIN_COMPONENT:  The business objects in PPDM that are related to this financial summary.  May be land rights, seismic acquisition or processing, well drilling/completions, etc.';
COMMENT ON TABLE L_FIN_COST_SUMMARY IS 'L_FIN_COST_SUMMARY:  This table is added to allow summaries of costs to be reported and allocated to various business objects.  This table is not intended to be used as an accounting system, but may contain summaries derived from the accounting system.';
COMMENT ON TABLE L_FIN_XREF IS 'L_FIN_XREF:  This table is used to create relationships between different finance information.';
COMMENT ON TABLE L_INTEREST_SET IS 'L_INTEREST_SET:  This table is based on INTEREST_SET from PPDM 3.7.';
COMMENT ON TABLE L_INT_SET_COMPONENT IS 'L_INT_SET_COMPONENT:  This table is used to associate working interest sets to actual items, such as Wells, Seismic, Land, Facilities, etc.';
COMMENT ON TABLE L_INT_SET_PARTNER IS 'L_INT_SET_PARTNER: This contains the partners in the working set as well as the percentages that they own.';
COMMENT ON TABLE L_LAND_ALIAS IS 'L_LAND_ALIAS:  An alternate name or file NUMERIC by which the land right may be known by.';
COMMENT ON TABLE L_LAND_RIGHT IS 'L_LAND_RIGHT:  Describes the right to land, either at the surface or subsurface rights level.  Land rights may be owned out right or leased through an agreement.  Relationships between land rights are found in the XREF table.';
COMMENT ON TABLE L_LAND_SALE IS 'L_LAND_SALE:  A public offering of lands for lease.  Government lessors usually offer leases through land sales so that resources can be developed.';
COMMENT ON TABLE L_LAND_SALE_OFFERING IS 'L_LAND_SALE_OFFERING:  Describes a parcel of land offered in a public land sale.  Many such offerings may be included in a single land sale.';
COMMENT ON TABLE L_LAND_XREF IS 'L_LAND_XREF:  Represents the relationships between different types of land rights.';
COMMENT ON TABLE L_LICENSE IS 'L_LICENSE:  This table is based on the various license tables from PPDM 3.7.  They include BA_LICENSE, FACILITY_LICENSE, SEIS_LICENSE and WELL_LICENSE.';
COMMENT ON TABLE L_PDEN IS 'L_PDEN:  This table represents any entity for which product  ion could be reported against.  This entity could be physical  installations such as a production well string, a spatial construct such as lease or reservoir or it could be an organizational concept  such as bus
-- iness unit.';
COMMENT ON TABLE L_PDEN_STRAT_UNIT IS 'L_PDEN_STRAT_UNIT:  All stratigraphic information for Producing Entities (PDEN) will be stored here.  This allows the storage of many strat units within a PDEN.';
COMMENT ON TABLE L_PDEN_VOL_SUMMARY IS 'L_PDEN_VOL_SUMMARY:  A summary of reported  volumes for common types of fluids over a specified time period.';
COMMENT ON TABLE L_PDEN_XREF IS 'L_PDEN_XREF: Another means of linking production entities to support relationships not explicitly defined in the PPDM  production model.';
COMMENT ON TABLE L_POOL IS 'L_POOL:  Represents a reservoir or group of small tracts of land brought together for the granting of a well permit under applicable spacing rules.';
COMMENT ON TABLE L_POOL_ALIAS IS 'L_POOL_ALIAS:  Pools may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_PPDM_COLUMN IS 'L_PPDM_COLUMN:  Contains meta data regarding the columns in the PPDM LITE schema.';
COMMENT ON TABLE L_PPDM_DATA_SOURCE IS 'L_PPDM_DATA_SOURCE:  This table is designed to store the different data sources that are used to populate PPDM LITE.  These data sources are meant to identify the SOURCE database system where the data came from.';
COMMENT ON TABLE L_PPDM_EXCEPTION IS 'L_PPDM_EXCEPTION:  This table was designed to hold any RDBMS errors that can occur during data loads.';
COMMENT ON TABLE L_PPDM_ORIGIN IS 'L_PPDM_ORIGIN:  This table is designed to track the row/column information from the source database to the target (PPDM Lite) database.';
COMMENT ON TABLE L_PPDM_TABLE IS 'L_PPDM_TABLE:  A meta data table that contains information regarding the tables contained within the PPDM Lite schema.';
COMMENT ON TABLE L_PROJECT IS 'L_PROJECT:  A project is an organized work effort directed towards accomplishing a recognized set of objectives or goals.  In the PPDM context, a project may be described in terms of its duration, location, funding and participants.';
COMMENT ON TABLE L_PROJECT_ALIAS IS 'L_PROJECT_ALIAS:  Projects may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_PROJECT_COMPONENT IS 'L_PROJECT_COMPONENT:  Lists the business objects from PPDM Lite that are associated with a project, such as wells, seismic, land, facilties, etc.';
COMMENT ON TABLE L_RESENT_CLASS IS 'L_RESENT_CLASS:  This table identifies the reserve classes which have been created for a given reserve entity.';
COMMENT ON TABLE L_RESENT_COMPONENT IS 'L_RESENT_COMPONENT:  This table identifies the product  components which have been created for a given reserve entity.';
COMMENT ON TABLE L_RESENT_XREF IS 'L_RESENT_XREF:  This table allows the merging or segragation of reserve entities to be tracked.';
COMMENT ON TABLE L_RESERVE_ENTITY IS 'L_RESERVE_ENTITY:  A reserve entity is a grouping of production objects (real or theoretical) that are grouped for the purposes of analyzing and forecasting production reserves.';
COMMENT ON TABLE L_RM_INFORMATION_ITEM IS 'L_RM_INFORMATION_ITEM:  Contains technical information that describes the information content of an item captured in the Recordsd Management module.';
COMMENT ON TABLE L_RM_INFO_ITEM_CONTENT IS 'L_RM_INFO_ITEM_CONTENT:  This table is used to associate an information item with the PPDM items that comprise it.';
COMMENT ON TABLE L_RM_INFO_ITEM_DESC IS 'L_RM_INFO_ITEM_DESC:  This veritical table may be used to capture specific details regarding the classification and description of an information item.';
COMMENT ON TABLE L_SEIS_ALIAS IS 'L_SEIS_ALIAS:  Alternate name for the seismic set.';
COMMENT ON TABLE L_SEIS_POINT IS 'L_SEIS_POINT:  a surface or subsurface point associated with a seismic  segment.  May be a shot, receiver, surveyed position, etc.    ';
COMMENT ON TABLE L_SEIS_RECORD IS 'L_SEIS_RECORD:  this table is used to capture details about seismic records.  It is not strictly necessary for an actual record to exist on a tape to use this table, although it is preferable.';
COMMENT ON TABLE L_SEIS_SET IS 'L_SEIS_SET:  This table is based on the SEIS_SET table from PPDM 3.7';
COMMENT ON TABLE L_SF_ALIAS IS 'L_SF_ALIAS:  Support Facilities may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_SF_COMPONENT IS 'L_SF_COMPONENT:  this table is used to track relationships between support facilities of all types and other business objects.  For example, you can track the relationship between a well and the road that services it, or the relationship between a well and the pad
--  or platform on which it is constructed.  Could also be used to track the roads used to service a well and the rate schedule applied to its use.';
COMMENT ON TABLE L_SF_DESCRIPTION IS 'L_SF_DESCRIPTION:   A list of descriptive details about a support facility.  This table is vertical to support the extremely wide range of descriptions possible, depending on the type of support facility.';
COMMENT ON TABLE L_SF_SUPPORT_FACILITY IS 'L_SF_SUPPORT_FACILITY:  A support facility provides operational support for an activity.  These facilities may include roads, transmission towers, airstrips, vessels, docks and so on.';
COMMENT ON TABLE L_SF_XREF IS 'L_SF_XREF:  This table is used to capture relationships between support facilities.  You can use this table to track the associations between road segments, towers and roads, bridges and roads, etc.';
COMMENT ON TABLE L_SPATIAL_DESCRIPTION IS 'L_SPATIAL_DESCRIPTION:  This table contains the surface and sub-surface description of land (or water).';
COMMENT ON TABLE L_SP_BOUNDARY IS 'L_SP_BOUNDARY:  This table contains the points which outline the perimeter of a polygon.  The points are sequenced spatially in either a clockwise or counter clockwise direction, as specified in L_SP_POLYGON.';
COMMENT ON TABLE L_SP_COMPONENT IS 'L_SP_COMPONENT:  This table is based on the SP_COMPONENT table from PPDM 3.7.  It is different because it will contain the relationships between the relational object (wells, pden, land, etc) with the spatial coordinates for it.';
COMMENT ON TABLE L_SP_GEOMETRY IS 'L_SP_GEOMETRY:  This table provides a method for spatially enabling descriptions through association with appropriate geometries in a spatial engine, such as SDE.';
COMMENT ON TABLE L_SP_LINE IS 'L_SP_LINE:  This is a table about a line that describes the linear extent of a spatial object such as a road, pipeline or transmission line.';
COMMENT ON TABLE L_SP_LINE_POINT IS 'L_SP_LINE_POINT:  This table contains the points along a line.';
COMMENT ON TABLE L_SP_MINERAL_ZONE IS 'L_SP_MINERAL_ZONE:  Definition of the subsurface that is included in the spatial description.';
COMMENT ON TABLE L_SP_POINT IS 'L_SP_POINT:  This is a position for which a location is permanently tracked.';
COMMENT ON TABLE L_SP_POLYGON IS 'L_SP_POLYGON:  This table describes a polygon that holds the outline of an areal.  Polygons may describe outlines of fields, pools, AOI agreements, land titles, land parcels, surface restrictions, etc.';
COMMENT ON TABLE L_SP_ZONE_SUBSTANCE IS 'L_SP_ZONE_SUBSTANCE:  This table describes substances which are specifically included or excluded from the spatial description.  For example, land rights may be granted from surface to basement, except for GAS in ZONE A.';
COMMENT ON TABLE L_STRAT_NAME_SET IS 'L_STRAT_NAME_SET:  A stratigraphic name set is an unordered collection of stratigraphic units, that may be in use for a Lexicon, a geographic area, a project, a company, etc.';
COMMENT ON TABLE L_STRAT_UNIT IS 'L_STRAT_UNIT: A  body of rock, of significant and distinctive  occurrence, distinguished from adjacent rock bodies on  the basis of  any one or more primary properties or attributes that rocks  possess,  such as mineral or fossil assemblages  lithologic characterist
-- ics,  environment and other natural  occurrences.';
COMMENT ON TABLE L_STRAT_WELL_SECTION IS 'L_STRAT_WELL_SECTION:  This table contains information on well tops.  This includes pick data on formations, markers, contacts and horizons that can be correlated from well to well within a geographic area.';
COMMENT ON TABLE L_WELL IS 'L_WELL:  This table is based on three tables from PPDM 3.7;  WELL, PDEN, WELL_LICENSE.';
COMMENT ON TABLE L_WELL_ALIAS IS 'L_WELL_ALIAS:  Wells may be known by more than one name.  Variations can be stored here.';
COMMENT ON TABLE L_WELL_SERVICE IS 'L_WELL_SERVICE:  This table is a roll-up table that was designed to allow very select but very
-- common information, such as TYPE or STRATIGRAPHIC or DEPTH information to be displayed/queried.
-- This table is used to capture any uwi based data from any table in PPDM 3.7 where uwi is a Foreign Key.';


